% Robust OED under model mismatch.
%
% Goal:
%   Compare ordinary FIM/E-optimal frequency selection with robust
%   frequency selection when the real HFT response is generated by a richer
%   model than the reduced identification model.
%
% Truth model:
%   asymmetric two-port + Rac(f) + Lsigma(f) + Cg1/Cg2 + loss terms.
%
% Identification model:
%   reduced symmetric 4-parameter model:
%       theta = [Lsigma, Cps, Cg, Rac]
%   with fixed Gg.

clear; clc; close all;
rng(20260711);

scriptDir = fileparts(mfilename('fullpath'));
projectDir = fileparts(scriptDir);
dataDir = fullfile(projectDir, char([25968 25454]));
if ~exist(dataDir, 'dir')
    mkdir(dataDir);
end

channels = {'Y11','Y12','Y22'};
paramNames = {'Lsigma','Cps','Cg','Rac'};

nCandidate = 260;
fCand = logspace(3, 7, nCandidate);
wCand = 2*pi*fCand;
K = 40;

% A deliberately richer "truth" model. It stays close to the earlier
% nominal values, but includes structure-like asymmetry and frequency
% dependence.
truth.Ls1 = 1.7e-6;
truth.Ls2 = 2.4e-6;
truth.kL1 = 0.045;      % Ls1(f) = Ls1 * (1 + kL1*log10(1+f/100kHz))
truth.kL2 = 0.070;
truth.Rdc1 = 0.08;
truth.Rdc2 = 0.11;
truth.kac1 = 0.055;     % Rac1(f) = Rdc1 + kac1*sqrt(f/1MHz)
truth.kac2 = 0.075;
truth.C12 = 85e-12;
truth.Cg1 = 95e-12;
truth.Cg2 = 150e-12;
truth.Gg1 = 0.6e-6;
truth.Gg2 = 1.4e-6;
truth.G12 = 0.15e-6;

thetaNom = [2.0e-6, 80e-12, 120e-12, 0.20];
GgFixed = 1.0e-6;

% Measurement noise weighted by the previously selected useful PWM condition.
pwm.tr = 50e-9;
pwm.fs = 500e3;
pwm.duty = 0.3;
U2 = pwm_spectrum_weight(fCand, pwm.fs, pwm.duty, pwm.tr);
baseRelNoise = 0.006;
noiseFloor = 0.03;
relSigma = min(baseRelNoise ./ sqrt(noiseFloor + U2), 0.12);

% Build frequency-wise FIM contributions for several possible reduced-model
% parameter samples. Robust design is done on the reduced model family, and
% then tested on the richer truth model.
nPrior = 28;
thetaPrior = sample_reduced_prior(thetaNom, nPrior);
contribNominal = fim_contributions_reduced(wCand, thetaNom, GgFixed, channels, relSigma);
contribPrior = zeros(size(contribNominal,1), size(contribNominal,2), nCandidate, nPrior);
for p = 1:nPrior
    contribPrior(:,:,:,p) = fim_contributions_reduced(wCand, thetaPrior(p,:), GgFixed, channels, relSigma);
end
contribPriorAvg = mean(contribPrior, 4);

idxUniform = pad_to_k(unique(round(linspace(1, nCandidate, K))), nCandidate, K);
idxNominal = sort(greedy_eopt_select(contribNominal, K));
idxPriorAvg = sort(greedy_eopt_select(contribPriorAvg, K));
idxRobustWorst = sort(greedy_robust_worst_eopt_select(contribPrior, K));
idxBandRobust = sort(band_limited_robust_select(contribPrior, fCand, K, 8));
idxRandom = sort(randperm(nCandidate, K));

strategies = struct([]);
strategies(1).name = "uniform_40";
strategies(1).idx = idxUniform;
strategies(2).name = "random_40";
strategies(2).idx = idxRandom;
strategies(3).name = "nominal_eopt_40";
strategies(3).idx = idxNominal;
strategies(4).name = "prior_avg_eopt_40";
strategies(4).idx = idxPriorAvg;
strategies(5).name = "robust_worst_eopt_40";
strategies(5).idx = idxRobustWorst;
strategies(6).name = "band_robust_eopt_40";
strategies(6).idx = idxBandRobust;
strategies(7).name = "full_260";
strategies(7).idx = 1:nCandidate;

nTrials = 28;
Tmc = run_mismatch_mc(fCand, truth, thetaNom, GgFixed, channels, relSigma, strategies, nTrials, paramNames);
writetable(Tmc, fullfile(dataDir, 'robust_oed_mismatch_summary.csv'));

designT = design_diagnostics(strategies, contribNominal, contribPrior);
writetable(designT, fullfile(dataDir, 'robust_oed_design_diagnostics.csv'));

% Fit full response once for visual comparison.
HrichFull = select_channels(rich_twoport_y(wCand, truth), channels);
measStdFull = relSigma(:).' .* max(abs(HrichFull), 1e-12);
[thetaFitFull, fitCostFull] = estimate_theta(wCand, HrichFull, measStdFull, thetaNom, GgFixed, channels);
HfitFull = select_channels(reduced_twoport_y(wCand, thetaFitFull, GgFixed), channels);
relFitErrFull = abs(HfitFull - HrichFull) ./ max(abs(HrichFull), 1e-12);

save(fullfile(dataDir, 'robust_oed_mismatch_demo.mat'), ...
    'Tmc', 'designT', 'truth', 'thetaNom', 'thetaPrior', 'GgFixed', ...
    'fCand', 'relSigma', 'idxUniform', 'idxRandom', 'idxNominal', ...
    'idxPriorAvg', 'idxRobustWorst', 'idxBandRobust', 'thetaFitFull', 'fitCostFull', ...
    'HrichFull', 'HfitFull', 'relFitErrFull');

plot_robust_oed_results(Tmc, designT, fCand, strategies, HrichFull, HfitFull, relFitErrFull, dataDir);
write_report(Tmc, designT, truth, thetaNom, thetaFitFull, fitCostFull, dataDir);
disp(Tmc);
disp(designT);

function thetaPrior = sample_reduced_prior(thetaNom, nPrior)
    % Lognormal prior. Cg and Rac are allowed slightly wider variation,
    % because they tend to absorb model mismatch in the reduced model.
    sigma = [0.22, 0.25, 0.32, 0.35];
    thetaPrior = zeros(nPrior, numel(thetaNom));
    thetaPrior(1,:) = thetaNom;
    for i = 2:nPrior
        thetaPrior(i,:) = thetaNom .* exp(sigma .* randn(size(thetaNom)));
    end
end

function idx = pad_to_k(idx, nCandidate, K)
    idx = idx(:).';
    if numel(idx) >= K
        idx = idx(1:K);
        return;
    end
    extra = setdiff(1:nCandidate, idx, 'stable');
    idx = sort([idx, extra(1:(K-numel(idx)))]);
end

function selected = greedy_eopt_select(contrib, K)
    nFreq = size(contrib, 3);
    selected = zeros(1, K);
    current = 1e-18 * eye(size(contrib,1));
    available = true(1, nFreq);
    for k = 1:K
        bestScore = -inf;
        bestIdx = 1;
        for i = find(available)
            score = min(eig(current + contrib(:,:,i)));
            if score > bestScore
                bestScore = score;
                bestIdx = i;
            end
        end
        selected(k) = bestIdx;
        current = current + contrib(:,:,bestIdx);
        available(bestIdx) = false;
    end
end

function selected = greedy_robust_worst_eopt_select(contribPrior, K)
    nFreq = size(contribPrior, 3);
    nPrior = size(contribPrior, 4);
    nParam = size(contribPrior, 1);
    selected = zeros(1, K);
    current = repmat(1e-18 * eye(nParam), 1, 1, nPrior);
    available = true(1, nFreq);
    for k = 1:K
        bestScore = -inf;
        bestIdx = 1;
        for i = find(available)
            scores = zeros(nPrior, 1);
            for p = 1:nPrior
                scores(p) = min(eig(current(:,:,p) + contribPrior(:,:,i,p)));
            end
            % Worst-case score, with a tiny average-score tie breaker.
            score = min(scores) + 1e-6 * mean(scores);
            if score > bestScore
                bestScore = score;
                bestIdx = i;
            end
        end
        selected(k) = bestIdx;
        for p = 1:nPrior
            current(:,:,p) = current(:,:,p) + contribPrior(:,:,bestIdx,p);
        end
        available(bestIdx) = false;
    end
end

function selected = band_limited_robust_select(contribPrior, fCand, K, nBand)
    % Coverage-constrained robust design.
    %
    % Plain E-opt can over-concentrate points in a narrow band. This helper
    % enforces broad log-frequency coverage first, then uses the same
    % worst-case E-opt score inside each band.
    edges = round(linspace(1, numel(fCand)+1, nBand+1));
    basePerBand = floor(K / nBand);
    remainder = K - basePerBand*nBand;
    selected = [];
    current = repmat(1e-18 * eye(size(contribPrior,1)), 1, 1, size(contribPrior,4));
    used = false(1, numel(fCand));
    for b = 1:nBand
        bandIdx = edges(b):(edges(b+1)-1);
        quota = basePerBand + double(b <= remainder);
        for q = 1:quota
            [bestIdx, current] = robust_pick_one(contribPrior, current, bandIdx(~used(bandIdx)));
            selected(end+1) = bestIdx; %#ok<AGROW>
            used(bestIdx) = true;
        end
    end
    selected = sort(selected);
end

function [bestIdx, current] = robust_pick_one(contribPrior, current, candidates)
    nPrior = size(contribPrior, 4);
    bestScore = -inf;
    bestIdx = candidates(1);
    for i = candidates
        scores = zeros(nPrior, 1);
        for p = 1:nPrior
            scores(p) = min(eig(current(:,:,p) + contribPrior(:,:,i,p)));
        end
        score = min(scores) + 1e-6 * mean(scores);
        if score > bestScore
            bestScore = score;
            bestIdx = i;
        end
    end
    for p = 1:nPrior
        current(:,:,p) = current(:,:,p) + contribPrior(:,:,bestIdx,p);
    end
end

function T = design_diagnostics(strategies, contribNominal, contribPrior)
    nPrior = size(contribPrior, 4);
    rows = [];
    for s = 1:numel(strategies)
        idx = strategies(s).idx;
        Fnom = sum(contribNominal(:,:,idx), 3);
        priorEig = zeros(nPrior, 1);
        priorLogdet = zeros(nPrior, 1);
        for p = 1:nPrior
            F = sum(contribPrior(:,:,idx,p), 3);
            e = eig(F + 1e-18*eye(size(F,1)));
            priorEig(p) = min(e);
            priorLogdet(p) = sum(log(max(e, 1e-300)));
        end
        eNom = eig(Fnom + 1e-18*eye(size(Fnom,1)));
        rows(s).strategy = string(strategies(s).name); %#ok<AGROW>
        rows(s).K = numel(idx);
        rows(s).nominalLambdaMin = min(eNom);
        rows(s).priorWorstLambdaMin = min(priorEig);
        rows(s).priorMeanLambdaMin = mean(priorEig);
        rows(s).priorMeanLogDet = mean(priorLogdet);
    end
    T = struct2table(rows);
end

function contrib = fim_contributions_reduced(w, theta, GgFixed, channels, relSigma)
    nFreq = numel(w);
    nParam = numel(theta);
    contrib = zeros(nParam, nParam, nFreq);
    for k = 1:nFreq
        S = reduced_sensitivity(w(k), theta, GgFixed, channels);
        H = select_channels(reduced_twoport_y(w(k), theta, GgFixed), channels);
        sigma = relSigma(k) * max(abs(H(:)), 1e-12);
        W = repmat(1 ./ sigma(:).^2, 1, nParam);
        contrib(:,:,k) = real(S' * (S .* W));
    end
end

function S = reduced_sensitivity(w, theta, GgFixed, channels)
    nParam = numel(theta);
    H0 = select_channels(reduced_twoport_y(w, theta, GgFixed), channels);
    S = zeros(numel(H0), nParam);
    step = 1e-4;
    for p = 1:nParam
        tp = theta; tm = theta;
        tp(p) = theta(p) * exp(step);
        tm(p) = theta(p) * exp(-step);
        Hp = select_channels(reduced_twoport_y(w, tp, GgFixed), channels);
        Hm = select_channels(reduced_twoport_y(w, tm, GgFixed), channels);
        S(:,p) = reshape((Hp-Hm)/(2*step), [], 1);
    end
end

function Tmc = run_mismatch_mc(fCand, truth, thetaNom, GgFixed, channels, relSigma, strategies, nTrials, paramNames)
    rows = [];
    wCand = 2*pi*fCand;
    for iStrat = 1:numel(strategies)
        idx = strategies(iStrat).idx;
        w = wCand(idx);
        sigmaRel = relSigma(idx);
        Htrue = select_channels(rich_twoport_y(w, truth), channels);
        measStd = sigmaRel(:).' .* max(abs(Htrue), 1e-12);
        thetaHat = nan(nTrials, numel(thetaNom));
        fitRelErr = nan(nTrials, 1);

        for t = 1:nTrials
            noise = (randn(size(Htrue)) + 1i*randn(size(Htrue))) ./ sqrt(2) .* measStd;
            Hmeas = Htrue + noise;
            thetaHat(t,:) = estimate_theta(w, Hmeas, measStd, thetaNom, GgFixed, channels);
            Hhat = select_channels(reduced_twoport_y(w, thetaHat(t,:), GgFixed), channels);
            fitRelErr(t) = mean(abs(Hhat(:)-Htrue(:)) ./ max(abs(Htrue(:)), 1e-12));
        end

        relErrToNom = (thetaHat - thetaNom) ./ thetaNom;
        rows(iStrat).strategy = string(strategies(iStrat).name); %#ok<AGROW>
        rows(iStrat).K = numel(idx);
        rows(iStrat).meanFitRelErrPct = 100 * mean(fitRelErr);
        rows(iStrat).stdFitRelErrPct = 100 * std(fitRelErr);
        for p = 1:numel(paramNames)
            rows(iStrat).(['meanEff_', paramNames{p}]) = mean(thetaHat(:,p));
            rows(iStrat).(['stdPct_', paramNames{p}]) = 100 * std(relErrToNom(:,p));
            rows(iStrat).(['shiftPct_', paramNames{p}]) = 100 * mean(relErrToNom(:,p));
        end
    end
    Tmc = struct2table(rows);
    Tmc = sortrows(Tmc, 'meanFitRelErrPct', 'ascend');
end

function [thetaBest, bestCost] = estimate_theta(w, Hmeas, measStd, thetaNom, GgFixed, channels)
    logNom = log(thetaNom);
    starts = [
         0,     0,     0,     0
         0.10, -0.10,  0.08,  0.08
        -0.12,  0.10, -0.08, -0.08
         0.25,  0.18, -0.16,  0.12
        -0.25, -0.18,  0.16, -0.12
    ];
    bestCost = inf;
    thetaBest = thetaNom;
    opts = optimset('Display','off', 'MaxIter', 900, 'MaxFunEvals', 3500, ...
        'TolX', 1e-8, 'TolFun', 1e-8);
    for i = 1:size(starts,1)
        x0 = logNom + starts(i,:);
        obj = @(x) objective(x, w, Hmeas, measStd, thetaNom, GgFixed, channels);
        [x, cost] = fminsearch(obj, x0, opts);
        if cost < bestCost
            bestCost = cost;
            thetaBest = exp(x);
        end
    end
end

function cost = objective(logTheta, w, Hmeas, measStd, thetaPrior, GgFixed, channels)
    theta = exp(logTheta);
    Hhat = select_channels(reduced_twoport_y(w, theta, GgFixed), channels);
    r = [(real(Hhat-Hmeas) ./ measStd), (imag(Hhat-Hmeas) ./ measStd)];
    cost = sum(huber_loss(r(:), 1.5));
    cost = cost + 0.01 * sum(((logTheta - log(thetaPrior)) ./ 0.9).^2);
end

function rho = huber_loss(r, delta)
    a = abs(r);
    rho = 0.5 * r.^2;
    idx = a > delta;
    rho(idx) = delta * (a(idx) - 0.5*delta);
end

function Y = rich_twoport_y(w, truth)
    f = w(:).'/(2*pi);
    s = 1i*w(:).';
    Ls1f = truth.Ls1 .* (1 + truth.kL1 .* log10(1 + f/1e5));
    Ls2f = truth.Ls2 .* (1 + truth.kL2 .* log10(1 + f/1e5));
    Rac1 = truth.Rdc1 + truth.kac1 * sqrt(f/1e6);
    Rac2 = truth.Rdc2 + truth.kac2 * sqrt(f/1e6);
    ys1 = 1 ./ (Rac1 + s.*Ls1f);
    ys2 = 1 ./ (Rac2 + s.*Ls2f);
    y12c = truth.G12 + s*truth.C12;
    yg1 = truth.Gg1 + s*truth.Cg1;
    yg2 = truth.Gg2 + s*truth.Cg2;
    ys = 2 ./ (1./ys1 + 1./ys2);
    Y11 = yg1 + y12c + ys;
    Y22 = yg2 + y12c + ys;
    Y12 = -y12c - ys;
    Y = zeros(2,2,numel(w));
    Y(1,1,:) = Y11;
    Y(2,2,:) = Y22;
    Y(1,2,:) = Y12;
    Y(2,1,:) = Y12;
end

function Y = reduced_twoport_y(w, theta, GgFixed)
    Lsigma = theta(1);
    Cps = theta(2);
    Cg = theta(3);
    Rac = theta(4);
    s = 1i*w(:).';
    ys = 1 ./ (Rac + s*Lsigma);
    yps = s*Cps;
    yg = GgFixed + s*Cg;
    Y11 = yg + yps + ys;
    Y22 = yg + yps + ys;
    Y12 = -yps - ys;
    Y = zeros(2,2,numel(w));
    Y(1,1,:) = Y11;
    Y(2,2,:) = Y22;
    Y(1,2,:) = Y12;
    Y(2,1,:) = Y12;
end

function H = select_channels(Y, channels)
    nFreq = size(Y,3);
    H = zeros(numel(channels), nFreq);
    for k = 1:numel(channels)
        switch channels{k}
            case 'Y11'
                H(k,:) = reshape(Y(1,1,:), 1, nFreq);
            case 'Y12'
                H(k,:) = reshape(Y(1,2,:), 1, nFreq);
            case 'Y22'
                H(k,:) = reshape(Y(2,2,:), 1, nFreq);
        end
    end
end

function U2 = pwm_spectrum_weight(f, fs, duty, tr)
    x = f / fs;
    dutyEnvelope = abs(sin(pi*duty*x) ./ max(pi*x, 1e-12));
    riseEnvelope = abs(sinc_local(f*tr));
    U2 = (dutyEnvelope .* riseEnvelope).^2;
    U2 = U2(:).' / max(U2(:));
end

function y = sinc_local(x)
    y = ones(size(x));
    nz = abs(x) > 1e-12;
    y(nz) = sin(pi*x(nz)) ./ (pi*x(nz));
end

function plot_robust_oed_results(Tmc, designT, fCand, strategies, Hrich, Hfit, relFitErr, dataDir)
    figure('Color','w','Position',[100,100,1080,430]);
    bar(1:height(Tmc), Tmc.meanFitRelErrPct);
    set(gca, 'XTick', 1:height(Tmc), 'XTickLabel', cellstr(Tmc.strategy));
    xtickangle(20);
    ylabel('Mean response fit error (%)');
    title('Model-mismatch MC: rich truth, reduced identification model');
    grid on;
    saveas(gcf, fullfile(dataDir, 'robust_oed_mismatch_fit_error.png'));

    figure('Color','w','Position',[100,100,1080,520]);
    hold on;
    marks = {'o','x','+','s','d','.'};
    for s = 1:numel(strategies)
        idx = strategies(s).idx;
        if numel(idx) > 80
            continue;
        end
        semilogx(fCand(idx), s*ones(size(idx)), marks{1+mod(s-1,numel(marks))}, 'DisplayName', strategies(s).name);
    end
    ylim([0.5, numel(strategies)+0.5]);
    set(gca, 'YTick', 1:numel(strategies), 'YTickLabel', {strategies.name});
    xlabel('Frequency (Hz)');
    title('Selected frequency points');
    grid on;
    saveas(gcf, fullfile(dataDir, 'robust_oed_selected_points.png'));

    figure('Color','w','Position',[100,100,1080,430]);
    cats = categorical(cellstr(designT.strategy));
    cats = reordercats(cats, cellstr(designT.strategy));
    semilogy(cats, designT.priorWorstLambdaMin, 'o-', 'LineWidth', 1.2); hold on;
    semilogy(cats, designT.priorMeanLambdaMin, 's-', 'LineWidth', 1.2);
    ylabel('lambda min(FIM)');
    title('Design robustness diagnostics over reduced-model prior');
    legend('worst prior sample','mean prior sample','Location','best');
    grid on;
    saveas(gcf, fullfile(dataDir, 'robust_oed_design_diagnostics.png'));

    figure('Color','w','Position',[100,100,1000,640]);
    chNames = {'Y11','Y12','Y22'};
    for k = 1:3
        subplot(3,1,k);
        loglog(fCand, abs(Hrich(k,:)), 'k-', 'LineWidth', 1.4); hold on;
        loglog(fCand, abs(Hfit(k,:)), 'r--', 'LineWidth', 1.1);
        grid on;
        ylabel(['|', chNames{k}, '|']);
        if k == 1
            title('Rich truth versus full-band reduced-model fit');
            legend('Rich truth','Reduced fit','Location','best');
        end
        if k == 3
            xlabel('Frequency (Hz)');
        end
    end
    saveas(gcf, fullfile(dataDir, 'robust_oed_fullband_response_fit.png'));

    figure('Color','w','Position',[100,100,980,420]);
    loglog(fCand, mean(relFitErr,1), 'LineWidth', 1.4);
    grid on;
    xlabel('Frequency (Hz)');
    ylabel('Mean relative response error');
    title('Full-band reduced-model fit error against rich truth');
    saveas(gcf, fullfile(dataDir, 'robust_oed_fullband_response_error.png'));
end

function write_report(Tmc, designT, truth, thetaNom, thetaFit, fitCost, dataDir)
    fid = fopen(fullfile(dataDir, 'robust_oed_mismatch_report.md'), 'w');
    fprintf(fid, '# Robust OED mismatch experiment\n\n');
    fprintf(fid, 'Generated: %s\n\n', datestr(now, 'yyyy-mm-dd HH:MM:SS'));
    fprintf(fid, '## Purpose\n\n');
    fprintf(fid, 'Compare uniform, random, nominal E-opt, prior-averaged E-opt, and worst-case robust E-opt frequency selection under model mismatch.\n\n');
    fprintf(fid, '## Truth model\n\n');
    fprintf(fid, '- asymmetric two-port\n');
    fprintf(fid, '- Rac(f) on both ports\n');
    fprintf(fid, '- Lsigma(f) on both ports\n');
    fprintf(fid, '- Cg1/Cg2 asymmetry and weak loss terms\n\n');
    fprintf(fid, 'Ls1=%.3e H, Ls2=%.3e H, C12=%.3e F, Cg1=%.3e F, Cg2=%.3e F.\n\n', ...
        truth.Ls1, truth.Ls2, truth.C12, truth.Cg1, truth.Cg2);
    fprintf(fid, '## Reduced identification model\n\n');
    fprintf(fid, 'theta=[Lsigma,Cps,Cg,Rac], fixed Gg=1e-6 S.\n\n');
    fprintf(fid, 'Nominal theta: %.3e, %.3e, %.3e, %.3e.\n\n', thetaNom);
    fprintf(fid, 'Full-band best equivalent theta: %.3e, %.3e, %.3e, %.3e, cost=%.3e.\n\n', thetaFit, fitCost);
    fprintf(fid, '## Monte Carlo response-fit error\n\n');
    fprintf(fid, '| strategy | K | meanFitRelErrPct | stdFitRelErrPct |\n');
    fprintf(fid, '|---|---:|---:|---:|\n');
    for i = 1:height(Tmc)
        fprintf(fid, '| %s | %d | %.4g | %.4g |\n', Tmc.strategy(i), Tmc.K(i), Tmc.meanFitRelErrPct(i), Tmc.stdFitRelErrPct(i));
    end
    fprintf(fid, '\n## Design diagnostics\n\n');
    fprintf(fid, '| strategy | K | nominalLambdaMin | priorWorstLambdaMin | priorMeanLambdaMin |\n');
    fprintf(fid, '|---|---:|---:|---:|---:|\n');
    for i = 1:height(designT)
        fprintf(fid, '| %s | %d | %.4e | %.4e | %.4e |\n', designT.strategy(i), designT.K(i), ...
            designT.nominalLambdaMin(i), designT.priorWorstLambdaMin(i), designT.priorMeanLambdaMin(i));
    end
    fprintf(fid, '\n## Initial interpretation\n\n');
    fprintf(fid, 'This is the first closed-loop robust-OED test. If robust_worst_eopt improves the worst-prior FIM but not the rich-truth response error, the next step is mismatch-aware or Bayesian OED that evaluates expected fit error rather than only reduced-model FIM.\n');
    fclose(fid);
end
